public int[][] merge(int[][] intervals) {
    Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));
    List<int[]> res = new ArrayList<>();
    for (int[] cur : intervals) {
        if (res.isEmpty() || res.get(res.size() - 1)[1] < cur[0]) {
            res.add(new int[]{cur[0], cur[1]});
        } else {
            int[] last = res.get(res.size() - 1);
            last[1] = Math.max(last[1], cur[1]);
        }
    }
    return res.toArray(new int[res.size()][]);
}

public int[][] insert(int[][] intervals, int[] newInterval) {
    List<int[]> res = new ArrayList<>();
    int i = 0, n = intervals.length;
    int lo = newInterval[0], hi = newInterval[1];
    while (i < n && intervals[i][1] < lo) res.add(intervals[i++]);
    while (i < n && intervals[i][0] <= hi) {
        lo = Math.min(lo, intervals[i][0]);
        hi = Math.max(hi, intervals[i][1]);
        i++;
    }
    res.add(new int[]{lo, hi});
    while (i < n) res.add(intervals[i++]);
    return res.toArray(new int[res.size()][]);
}

public int minMeetingRooms(int[][] intervals) {
    Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));
    PriorityQueue<Integer> pq = new PriorityQueue<>(); // end times of busy rooms
    for (int[] it : intervals) {
        if (!pq.isEmpty() && pq.peek() <= it[0]) pq.poll();
        pq.offer(it[1]);
    }
    return pq.size();
}

public int minMeetingRooms(int[][] intervals) {
    int n = intervals.length;
    int[] starts = new int[n], ends = new int[n];
    for (int i = 0; i < n; i++) { starts[i] = intervals[i][0]; ends[i] = intervals[i][1]; }
    Arrays.sort(starts);
    Arrays.sort(ends);
    int rooms = 0, max = 0, e = 0;
    for (int s = 0; s < n; s++) {
        while (e < n && ends[e] <= starts[s]) { rooms--; e++; }
        rooms++;
        max = Math.max(max, rooms);
    }
    return max;
}

public int eraseOverlapIntervals(int[][] intervals) {
    Arrays.sort(intervals, (a, b) -> Integer.compare(a[1], b[1]));
    int removed = 0;
    long prevEnd = Long.MIN_VALUE;
    for (int[] it : intervals) {
        if (it[0] >= prevEnd) {
            prevEnd = it[1];
        } else {
            removed++;
        }
    }
    return removed;
}

class Interval {
    public int start, end;
    public Interval() {}
    public Interval(int start, int end) { this.start = start; this.end = end; }
}

public List<Interval> employeeFreeTime(List<List<Interval>> schedule) {
    List<Interval> all = new ArrayList<>();
    for (List<Interval> emp : schedule) all.addAll(emp);
    all.sort((a, b) -> Integer.compare(a.start, b.start));
    List<Interval> res = new ArrayList<>();
    int prevEnd = all.get(0).end;
    for (Interval iv : all) {
        if (iv.start > prevEnd) {
            res.add(new Interval(prevEnd, iv.start));
            prevEnd = iv.end;
        } else {
            prevEnd = Math.max(prevEnd, iv.end);
        }
    }
    return res;
}

public int findMinArrowShots(int[][] points) {
    Arrays.sort(points, (a, b) -> Integer.compare(a[1], b[1]));
    int arrows = 1;
    long arrow = points[0][1];
    for (int[] p : points) {
        if (p[0] > arrow) {
            arrows++;
            arrow = p[1];
        }
    }
    return arrows;
}

class SummaryRanges {
    private TreeMap<Integer, int[]> tree;

    public SummaryRanges() {
        tree = new TreeMap<>();
    }

    public void addNum(int value) {
        if (tree.containsKey(value)) return;
        Integer lo = tree.lowerKey(value);
        Integer hi = tree.higherKey(value);
        boolean touchLo = lo != null && tree.get(lo)[1] + 1 >= value;
        boolean touchHi = hi != null && value + 1 == hi;
        if (touchLo && touchHi) {
            tree.get(lo)[1] = tree.get(hi)[1];
            tree.remove(hi);
        } else if (touchLo) {
            tree.get(lo)[1] = Math.max(tree.get(lo)[1], value);
        } else if (touchHi) {
            tree.put(value, new int[]{value, tree.get(hi)[1]});
            tree.remove(hi);
        } else {
            tree.put(value, new int[]{value, value});
        }
    }

    public int[][] getIntervals() {
        int[][] res = new int[tree.size()][];
        int i = 0;
        for (int[] iv : tree.values()) res[i++] = iv;
        return res;
    }
}

class RangeModule {
    private TreeMap<Integer, Integer> map; // start -> end (half-open [start, end))

    public RangeModule() {
        map = new TreeMap<>();
    }

    public void addRange(int left, int right) {
        Integer start = map.floorKey(left);
        Integer end = map.floorKey(right);
        if (start != null && map.get(start) >= left) left = start;
        if (end != null && map.get(end) > right) right = map.get(end);
        map.subMap(left, right).clear();
        map.put(left, right);
    }

    public boolean queryRange(int left, int right) {
        Integer start = map.floorKey(left);
        return start != null && map.get(start) >= right;
    }

    public void removeRange(int left, int right) {
        Integer start = map.floorKey(left);
        Integer end = map.floorKey(right);
        if (end != null && map.get(end) > right) map.put(right, map.get(end));
        if (start != null && map.get(start) > left) map.put(start, left);
        map.subMap(left, right).clear();
    }
}

public int jobScheduling(int[] startTime, int[] endTime, int[] profit) {
    int n = startTime.length;
    int[][] jobs = new int[n][3];
    for (int i = 0; i < n; i++) jobs[i] = new int[]{startTime[i], endTime[i], profit[i]};
    Arrays.sort(jobs, (a, b) -> Integer.compare(a[1], b[1]));
    TreeMap<Integer, Integer> dp = new TreeMap<>(); // endTime -> best profit up to endTime
    dp.put(0, 0);
    for (int[] job : jobs) {
        int best = dp.floorEntry(job[0]).getValue() + job[2];
        if (best > dp.lastEntry().getValue()) dp.put(job[1], best);
    }
    return dp.lastEntry().getValue();
}

class MyCalendarThree {
    private TreeMap<Integer, Integer> delta;

    public MyCalendarThree() {
        delta = new TreeMap<>();
    }

    public int book(int startTime, int endTime) {
        delta.merge(startTime, 1, Integer::sum);
        delta.merge(endTime, -1, Integer::sum);
        int active = 0, max = 0;
        for (int v : delta.values()) {
            active += v;
            max = Math.max(max, active);
        }
        return max;
    }
}

class MyCalendarTwo {
    private List<int[]> bookings;
    private List<int[]> overlaps;

    public MyCalendarTwo() {
        bookings = new ArrayList<>();
        overlaps = new ArrayList<>();
    }

    public boolean book(int start, int end) {
        for (int[] o : overlaps) {
            if (start < o[1] && o[0] < end) return false; // would triple-book
        }
        for (int[] b : bookings) {
            if (start < b[1] && b[0] < end) {
                overlaps.add(new int[]{Math.max(start, b[0]), Math.min(end, b[1])});
            }
        }
        bookings.add(new int[]{start, end});
        return true;
    }
}

public List<List<Integer>> getSkyline(int[][] buildings) {
    List<int[]> events = new ArrayList<>();
    for (int[] b : buildings) {
        events.add(new int[]{b[0], -b[2]}); // start: negative height
        events.add(new int[]{b[1],  b[2]}); // end:   positive height
    }
    // sort by x; ties: starts (neg) before ends (pos); among starts, taller (more negative) first
    events.sort((a, c) -> a[0] != c[0] ? Integer.compare(a[0], c[0]) : Integer.compare(a[1], c[1]));

    List<List<Integer>> res = new ArrayList<>();
    TreeMap<Integer, Integer> active = new TreeMap<>(); // height -> count
    active.put(0, 1); // ground level
    int prevMax = 0;
    for (int[] e : events) {
        int h = e[1];
        if (h < 0) {
            active.merge(-h, 1, Integer::sum);
        } else {
            int c = active.get(h);
            if (c == 1) active.remove(h); else active.put(h, c - 1);
        }
        int curMax = active.lastKey();
        if (curMax != prevMax) {
            res.add(Arrays.asList(e[0], curMax));
            prevMax = curMax;
        }
    }
    return res;
}

// Merge two skylines like merge-sort, tracking each side's current height.
public List<List<Integer>> getSkyline(int[][] buildings) {
    return divide(buildings, 0, buildings.length - 1);
}

private List<List<Integer>> divide(int[][] b, int lo, int hi) {
    List<List<Integer>> res = new ArrayList<>();
    if (lo > hi) return res;
    if (lo == hi) {
        res.add(Arrays.asList(b[lo][0], b[lo][2]));
        res.add(Arrays.asList(b[lo][1], 0));
        return res;
    }
    int mid = (lo + hi) >>> 1;
    List<List<Integer>> left = divide(b, lo, mid);
    List<List<Integer>> right = divide(b, mid + 1, hi);
    return mergeSkylines(left, right);
}

private List<List<Integer>> mergeSkylines(List<List<Integer>> a, List<List<Integer>> c) {
    List<List<Integer>> res = new ArrayList<>();
    int i = 0, j = 0, hA = 0, hC = 0, prev = -1;
    while (i < a.size() && j < c.size()) {
        int x;
        if (a.get(i).get(0) < c.get(j).get(0)) {
            x = a.get(i).get(0); hA = a.get(i).get(1); i++;
        } else if (a.get(i).get(0) > c.get(j).get(0)) {
            x = c.get(j).get(0); hC = c.get(j).get(1); j++;
        } else {
            x = a.get(i).get(0); hA = a.get(i).get(1); hC = c.get(j).get(1); i++; j++;
        }
        int h = Math.max(hA, hC);
        if (h != prev) { res.add(Arrays.asList(x, h)); prev = h; }
    }
    while (i < a.size()) {
        int x = a.get(i).get(0), h = a.get(i).get(1); i++;
        if (h != prev) { res.add(Arrays.asList(x, h)); prev = h; }
    }
    while (j < c.size()) {
        int x = c.get(j).get(0), h = c.get(j).get(1); j++;
        if (h != prev) { res.add(Arrays.asList(x, h)); prev = h; }
    }
    return res;
}
